function features(o,mode=9){return calibrationFeatures(o,mode)}
function dot(a,b){return a.reduce((s,v,i)=>s+v*b[i],0)}
function finitePoint(p){return p&&Number.isFinite(p.x)&&Number.isFinite(p.y)}
