    state.cameraConstraints={facingMode:"user",width:requestedWidth,height:requestedHeight};let resolutionFallback=false;
    try{state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user",width:{exact:requestedWidth},height:{exact:requestedHeight}},audio:false})}
    catch(error){if(error?.name!=="OverconstrainedError")throw error;resolutionFallback=true;state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user",width:{ideal:requestedWidth},height:{ideal:requestedHeight}},audio:false})}
    ui.video.srcObject=state.stream;await ui.video.play();state.cameraSize={width:ui.video.videoWidth,height:ui.video.videoHeight};state.cameraTrackSettings=state.stream.getVideoTracks()[0]?.getSettings?.()||null;updatePreviewAspect(state.cameraSize);resetPersonFraming();state.running=true;ui.stage.classList.add("live");ui.statusDot.classList.add("live");
