    ui.heroState.textContent="LIVE";ui.startCamera.textContent="CAMERA CONNECTED";ui.startCalibration.disabled=false;ui.reinitFace.disabled=false;ui.restartCamera.disabled=false;ui.registerHead.disabled=false;
