  cancelPendingDrift("calibration started");
  state.previousModelSnapshot=structuredClone({hasModel:Boolean(state.model.modelX),featureMode:state.model.featureMode,modelX:state.model.modelX,modelY:state.model.modelY,leftX:state.model.leftX,leftY:state.model.leftY,rightX:state.model.rightX,rightY:state.model.rightY,eyeResiduals:state.model.eyeResiduals,headRef:state.model.headRef,headGeometry:state.headGeometry,meta:state.calibrationMeta,drift:state.drift,adaptiveDriftModel:state.adaptiveDriftModel,driftHistory:state.driftHistory,tracking:state.tracking,eyeSphereLock:state.eyeSphereLock,pseudo3DGaze:state.pseudo3DGaze,headKeyframes:state.headKeyframes,candidateHeadRegistration:state.candidateHeadRegistration,calibrationStorage:localStorage.getItem(CALIBRATION_KEY),headStorage:localStorage.getItem(HEAD_KEYFRAMES_KEY)});
  state.drift={x:0,y:0};state.adaptiveDriftModel=createAdaptiveDriftModel();state.driftHistory=[];state.driftBuffer=[];state.driftArmed=false;ui.undoDrift.disabled=true;ui.resetDrift.disabled=true;updateDriftStatus("CALIBRATING");
  const targetCount=Number(ui.calibrationType.value),targets=CALIBRATION_TARGETS[targetCount]||CALIBRATION_TARGETS[9];
  state.tracking=false;state.gazeFilter=null;ui.gazeCursor.hidden=true;ui.calibrationOverlay.hidden=false;state.calibration={index:0,samples:[],events:[{type:"CAL_START",at:Date.now(),targetCount}],targets,cancelled:false};
