function toggleDrift(){state.driftEnabled=ui.driftToggle.checked;state.driftArmed=false;if(!state.driftEnabled)cancelPendingDrift("adaptive drift disabled");ui.armDrift.disabled=!state.driftEnabled;updateDriftStatus(state.driftEnabled?"READY":"OFF");setMessage(state.driftEnabled?"Adaptive drift enabled. Arm one deliberate target before clicking it.":"Adaptive drift disabled; its verified model is preserved.")}
function toggleDebug(){state.debugEnabled=ui.debugToggle.checked;ui.debugOverlay.hidden=!state.debugEnabled}
function toggleHeadPlot(){state.headPlotEnabled=ui.showHeadPlot.checked;ui.headPlot.hidden=!state.headPlotEnabled;if(state.headPlotEnabled&&state.latestObservation)drawHeadPlot(state.latestObservation.head)}
function armDrift(){if(!state.driftEnabled||!state.tracking)return;if(state.pendingDrift)return setMessage("Wait for the current drift target to finish verification before arming another.",true);state.driftArmed=true;ui.armDrift.textContent="CLICK INTENDED TARGET";setMessage("Drift target armed. Hold a steady gaze for at least 400 ms, then click that exact target once.")}
function undoDrift(){if(cancelPendingDrift("undo requested"))return;const prior=state.driftHistory.pop();if(!prior)return;if(prior.type==="center-health-correction"){state.drift={...prior.before};state.model.previous=null;state.gazeFilter=null;updateDriftStatus("CENTER UNDONE");return setMessage("Last center-health correction undone. The adaptive model is unchanged.")}if(prior.type!=="adaptive-rls"||!validateAdaptiveDriftModel(prior.beforeModel)){state.driftHistory.push(prior);updateDriftStatus("UNDO BLOCKED");return setMessage("The last correction could not be safely undone.",true)}state.adaptiveDriftModel=structuredClone(prior.beforeModel);state.model.previous=null;state.gazeFilter=null;updateDriftStatus("UNDONE");setMessage(`Last adaptive target undone. ${state.adaptiveDriftModel.accepted} trusted targets remain.`)}
function resetAdaptiveDrift(){state.pendingDrift=null;state.driftArmed=false;state.adaptiveDriftModel=createAdaptiveDriftModel();state.driftHistory=[];state.model.previous=null;state.gazeFilter=null;updateDriftStatus("RESET");setMessage("Adaptive drift model reset. The base calibration is unchanged.")}
function toggleVideo(){state.videoEnabled=ui.videoToggle.checked;setMessage(state.videoEnabled?`Webcam video will be recorded with the next gaze session${state.grayscaleVideoEnabled?" through the grayscale diagnostic pipeline":" in color"}.`:"Webcam video recording disabled.")}
function toggleGrayscaleVideo(){state.grayscaleVideoEnabled=ui.grayscaleVideoToggle.checked;setMessage(state.grayscaleVideoEnabled?"vSamples-style grayscale diagnostic recording enabled.":"Diagnostic recording will use the original color camera stream.")}
function changeEngine(){state.landmarkFilter=null;saveSettings();resetAdaptiveDrift();state.pupilTracks={left:null,right:null};state.eyePatches={left:null,right:null};state.eyeAlignment={left:null,right:null};state.eyeAlignmentDisagreement=false;state.activeEngine=selectedEngine();ui.activeEngine.textContent=selectedEngine().toUpperCase();ui.hybridConfidence.textContent=selectedEngine()==="hybrid"?"WAIT":"—";state.tracking=false;ui.toggleTracking.textContent="START TRACKING";clearCandidateModel();ui.heroCalibration.textContent="REQUIRED";setStep(ui.calibrationStep,"active");setMessage(selectedEngine()==="hybrid"?"Hybrid eye-image mode selected. Recalibrate so pupil, patch-flow and head features are mapped together; weak frames fall back to MediaPipe landmarks.":"MediaPipe landmark mode selected. Recalibration is required because eye features changed.")}
function adaptiveDriftClick(event){if(state.pendingDrift||!state.driftArmed||!state.driftEnabled||!state.tracking||event.target.closest("button,input,label,.control"))return;const now=performance.now(),window=state.driftBuffer.filter(s=>now-s.at<=700&&s.confidence>=.75&&s.binocular&&s.direct&&s.motion<=.04);state.driftArmed=false;ui.armDrift.textContent="ARM DRIFT TARGET";if(window.length<10||window.at(-1).at-window[0].at<400){updateDriftStatus("REJECTED");return setMessage("Correction rejected: hold a stable, binocular gaze for at least 400 ms before clicking.",true)}const xs=window.map(s=>s.base.x),ys=window.map(s=>s.base.y),dispersion=Math.hypot(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys));if(dispersion>.04){updateDriftStatus("REJECTED");return setMessage("Correction rejected: the fixation moved too much. Re-arm and hold still.",true)}const intended={x:event.clientX/innerWidth,y:event.clientY/innerHeight},anchor={base:{x:median(xs),y:median(ys)},head:{yaw:median(window.map(s=>s.head.yaw)),pitch:median(window.map(s=>s.head.pitch)),z:median(window.map(s=>s.head.z))},target:intended,confidence:median(window.map(s=>s.confidence)),at:Date.now()},beforeModel=structuredClone(state.adaptiveDriftModel),beforeCorrection=predictAdaptiveDrift(beforeModel,anchor.base,anchor.head),beforeError=Math.hypot(anchor.base.x+beforeCorrection.x-intended.x,anchor.base.y+beforeCorrection.y-intended.y);if(beforeError<.01){updateDriftStatus("NO CHANGE");return setMessage("No drift correction was needed: current error is already below 1% of the screen diagonal.")}const updated=updateAdaptiveDriftRls(beforeModel,anchor);if(!updated.accepted){state.adaptiveDriftModel.rejected++;updateDriftStatus("REJECTED");return setMessage(`Correction rejected: ${updated.reason.replaceAll("-"," ")}.`,true)}state.adaptiveDriftModel=updated.model;const audit={type:"adaptive-rls",timestamp:new Date().toISOString(),algorithm:"robust-rls-v1",beforeModel,afterModel:structuredClone(updated.model),anchor,beforeError,step:updated.step,accepted:null};state.driftHistory.push(audit);state.pendingDrift={audit,startedAt:now,beforeErrors:[],afterErrors:[]};state.model.previous=null;state.gazeFilter=null;updateDriftStatus("VERIFYING");setMessage(`Adaptive ${updated.model.mode.toUpperCase()} update applied with a ${Math.round(updated.step*1000)/10}% step; keep looking at the clicked target while it verifies.`)}
function verifyPendingDrift(result,obs){const pending=state.pendingDrift;if(!pending)return;const now=performance.now(),anchor=pending.audit.anchor,direct=!obs.leftEye.sourceHeld&&!obs.rightEye.sourceHeld&&obs.leftEye.confidence>=.75&&obs.rightEye.confidence>=.75,nearAnchor=Math.hypot(result.baseline.x-anchor.base.x,result.baseline.y-anchor.base.y)<.05,nearPose=Math.hypot((result.poseDelta.yaw-anchor.head.yaw)/26,(result.poseDelta.pitch-anchor.head.pitch)/22,(result.poseDelta.z-anchor.head.z)/3)<.28;if(result.confidence>=.75&&!result.binocularDegraded&&!state.eyeAlignmentDisagreement&&direct&&nearAnchor&&nearPose){const before=predictAdaptiveDrift(pending.audit.beforeModel,result.baseline,result.poseDelta),after=predictAdaptiveDrift(state.adaptiveDriftModel,result.baseline,result.poseDelta);pending.beforeErrors.push(Math.hypot(result.baseline.x+before.x-anchor.target.x,result.baseline.y+before.y-anchor.target.y));pending.afterErrors.push(Math.hypot(result.baseline.x+after.x-anchor.target.x,result.baseline.y+after.y-anchor.target.y))}if(pending.afterErrors.length<8&&now-pending.startedAt<1500)return;const beforeError=median(pending.beforeErrors),afterError=median(pending.afterErrors),improvement=beforeError-afterError,accepted=pending.afterErrors.length>=6&&Number.isFinite(afterError)&&afterError<=beforeError+.001&&(afterError<=beforeError*.98||improvement>=.002);pending.audit.afterError=afterError;pending.audit.verificationSamples=pending.afterErrors.length;pending.audit.accepted=accepted;if(!accepted){state.adaptiveDriftModel=structuredClone(pending.audit.beforeModel);const index=state.driftHistory.indexOf(pending.audit);if(index>=0)state.driftHistory.splice(index,1);updateDriftStatus("ROLLED BACK");setMessage("Adaptive correction rolled back because stable verification did not improve.",true)}else{updateDriftStatus();setMessage(`Adaptive correction verified: ${Math.round((1-afterError/Math.max(beforeError,.0001))*100)}% lower target error.`)}state.model.previous=null;state.gazeFilter=null;state.pendingDrift=null}

ui.startCamera.addEventListener("click",startCamera);ui.reinitFace.addEventListener("click",reinitializeFace);ui.restartCamera.addEventListener("click",restartCamera);ui.startCalibration.addEventListener("click",beginCalibration);ui.cancelCalibration.addEventListener("click",cancelCalibration);ui.toggleTracking.addEventListener("click",toggleTracking);ui.toggleRecording.addEventListener("click",toggleRecording);ui.exportCsv.addEventListener("click",exportCsv);ui.exportHeatmap.addEventListener("click",exportHeatmap);ui.exportSession.addEventListener("click",exportSession);ui.importSession.addEventListener("change",importSession);ui.downloadVideo.addEventListener("click",downloadVideo);ui.armDrift.addEventListener("click",armDrift);ui.undoDrift.addEventListener("click",undoDrift);ui.resetDrift.addEventListener("click",resetAdaptiveDrift);ui.bubbleToggle.addEventListener("change",toggleBubble);ui.heatmapToggle.addEventListener("change",toggleHeatmap);ui.pathToggle.addEventListener("change",togglePath);ui.driftToggle.addEventListener("change",toggleDrift);ui.debugToggle.addEventListener("change",toggleDebug);ui.videoToggle.addEventListener("change",toggleVideo);ui.clearHeatmap.addEventListener("click",clearHeatmap);ui.resultSettingsTab.addEventListener("click",()=>selectSettingsTab("result"));ui.trackerSettingsTab.addEventListener("click",()=>selectSettingsTab("tracker"));ui.pupilDistance.addEventListener("input",()=>ui.pupilDistanceValue.textContent=`${ui.pupilDistance.value} MM`);ui.calibrationType.addEventListener("change",()=>{ui.calibrationStep.querySelector("small").textContent=`Follow ${ui.calibrationType.value} targets while keeping a steady head pose.`});ui.showGazeSetting.addEventListener("change",()=>{ui.bubbleToggle.checked=ui.showGazeSetting.checked;toggleBubble()});ui.showHeadPlot.addEventListener("change",toggleHeadPlot);ui.registerHead.addEventListener("click",()=>registerHeadPose(false));ui.showAccuracy.addEventListener("click",showAccuracyReport);ui.closeAccuracy.addEventListener("click",closeAccuracyReport);ui.closeAccuracyBottom.addEventListener("click",closeAccuracyReport);ui.downloadAccuracy.addEventListener("click",downloadAccuracy);ui.generateResult.addEventListener("click",generateResult);ui.accuracyModal.addEventListener("click",e=>{if(e.target===ui.accuracyModal)closeAccuracyReport()});document.querySelectorAll(".settings-pane input,.settings-pane select").forEach(el=>el.addEventListener("change",saveSettings));addEventListener("keydown",e=>{if(e.key==="Escape"&&!ui.accuracyModal.hidden)closeAccuracyReport()});addEventListener("mousemove",e=>{if(state.recording&&ui.showMouse.checked&&(!state.mouseSamples.length||performance.now()-(state.mouseSamples.at(-1)?.capturedAt||0)>50))state.mouseSamples.push({x:e.clientX/innerWidth,y:e.clientY/innerHeight,elapsed:performance.now()-state.recordStart,capturedAt:performance.now()})});addEventListener("click",adaptiveDriftClick);
const sceneObserver=new MutationObserver(records=>{const relevant=records.filter(r=>!r.target.parentElement?.closest(".control,.live-panel,.telemetry,.settings-panel,.accuracy-modal,.debug-overlay"));if(!relevant.length)return;const total=Math.max(1,document.querySelectorAll("main *").length);state.sceneChangePercent=clamp(relevant.length/total*100,0,100);state.lastSceneMutationAt=performance.now()});sceneObserver.observe(document.querySelector("main"),{subtree:true,childList:true,characterData:true,attributes:true});
ui.gazeFilterToggle.addEventListener("change",()=>{state.gazeFilterEnabled=ui.gazeFilterToggle.checked;state.gazeFilter=null;state.model.previous=null;saveSettings();setMessage(state.gazeFilterEnabled?"Adaptive One Euro gaze filtering enabled. The next valid sample starts a fresh filter.":"Gaze filter disabled. The bubble now uses calibrated unfiltered output.")});
ui.centerCorrection.addEventListener("click",runCenterCorrection);
ui.stabilityTest.addEventListener("click",toggleStabilityTest);
ui.trackingEngine.addEventListener("change",changeEngine);
ui.grayscaleVideoToggle.addEventListener("change",toggleGrayscaleVideo);
ui.cameraResolution.addEventListener("change",()=>{state.landmarkFilter=null;updatePreviewAspect();invalidateEyeSphereLock()});
ui.trackingEngine.addEventListener("change",invalidateEyeSphereLock);ui.cameraFov.addEventListener("change",invalidateEyeSphereLock);ui.cameraLocation.addEventListener("change",invalidateEyeSphereLock);
ui.smartPersonCrop.addEventListener("change",()=>{if(!ui.smartPersonCrop.checked)resetPersonFraming()});
ui.cameraLocation.addEventListener("change",()=>{if(state.calibrationMeta&&state.calibrationMeta.settings?.tracker?.cameraLocation!==ui.cameraLocation.value){clearCandidateModel();ui.heroCalibration.textContent="REQUIRED";setStep(ui.calibrationStep,"active");setMessage("Webcam mounting location changed. Recalibrate for the new vertical convention.",true)}});
addEventListener("beforeunload",()=>{flushFixation();stopVideoRecording();cancelAnimationFrame(state.raf);state.stream?.getTracks().forEach(t=>t.stop());state.landmarker?.close()});
addEventListener("resize",()=>{sizeHeatmap();sizePath();if(state.pathEnabled)drawGazePath();const old=state.calibrationMeta?.viewport?.aspect;if(old&&Math.abs(innerWidth/innerHeight-old)>.15){ui.heroCalibration.textContent="CHECK";setMessage("Viewport aspect changed materially. Revalidate calibration for best accuracy.",true)}});
